          >
            {/* 1. Index */}
            <td className="py-2.5 px-3 text-center">
              <span className={`text-[10px] font-mono ${isCompleted ? 'text-emerald-400 font-bold' : 'text-hazard-textMuted/50'}`}>
                {index + 1}
              </span>
            </td>

            {/* 2. Completion Checkbox (Prominent Notion Checkbox) */}
            <td className="py-2.5 px-3 text-center" onClick={(e) => e.stopPropagation()}>
              <button
                type="button"
                onClick={() => updateEntryField(key, 'completed', !isCompleted)}
                title={isCompleted ? 'Marked Completed (Click to mark Draft/Incomplete)' : 'Draft (Click to mark Completed)'}
                className={`inline-flex items-center justify-center w-5 h-5 rounded-md border-2 transition-all duration-150 active:scale-90 ${
                  isCompleted
                    ? 'bg-emerald-500 border-emerald-400 text-black shadow-emerald-500/40 shadow-md scale-105'
                    : 'bg-hazard-card border-hazard-border hover:border-emerald-400 text-transparent'
                }`}
              >
                <Check className={`w-3.5 h-3.5 stroke-[3] ${isCompleted ? 'text-black' : 'opacity-0'}`} />
              </button>
            </td>

            {/* 3. Display Name, Hex Key & Image Thumbnail */}
            <td className="py-2.5 px-3">
              <div className="flex items-center gap-2">
                {/* Image preview / icon */}
                <div
                  onClick={() => {
                    const newUrl = window.prompt('Set Image URL for this option:', entry.image || '');
                    if (newUrl !== null) updateEntryField(key, 'image', newUrl.trim());
                  }}
                  title="Click to edit Image URL"
                  className="w-8 h-8 rounded-lg bg-hazard-card border border-hazard-border/80 overflow-hidden flex items-center justify-center shrink-0 cursor-pointer hover:border-hazard-gold transition"
                >
                  {entry.image || entry.thumbnail ? (
                    <img src={entry.image || entry.thumbnail} alt="" className="w-full h-full object-cover" />
                  ) : (
                    <Sparkles className="w-3.5 h-3.5 text-hazard-gold/40" />
                  )}
                </div>

                {/* In-place Editable Display Name & Hex Key */}
                <div className="flex flex-col min-w-0 flex-1">
                  <input
                    type="text"
                    value={entry.display_name || ''}
                    onChange={(e) => updateEntryField(key, 'display_name', e.target.value)}
                    placeholder="Display Name"
                    className="w-full bg-transparent hover:bg-hazard-card/60 focus:bg-hazard-card px-1.5 py-0.5 rounded text-xs font-bold text-hazard-textBright focus:text-hazard-gold outline-none transition"
                  />
                  <span
                    title={`Hex Key: ${key} (Click to copy)`}
                    onClick={() => navigator.clipboard.writeText(key)}
                    className="text-[9px] font-mono text-hazard-gold/70 px-1.5 py-0.2 rounded hover:bg-hazard-gold/20 cursor-pointer truncate max-w-[140px]"
                  >
                    {key}
                  </span>
                </div>
              </div>
            </td>

            {/* 3. Prompt Tokens (In-Place Textarea / Input) */}
            <td className="py-2.5 px-3">
              <textarea
                rows={2}
                value={entry.prompt || ''}
                onChange={(e) => updateEntryField(key, 'prompt', e.target.value)}
                placeholder="e.g. wet clothes, translucent shirt"
                className="w-full bg-transparent hover:bg-hazard-card/60 focus:bg-hazard-card p-1.5 rounded text-[11px] font-mono text-hazard-textBright outline-none leading-tight resize-none transition"
              />
            </td>

            {/* 4. Tag-Team (Inheritance Pills + Dropdown) */}
            <td className="py-2.5 px-3">
              <div className="flex flex-wrap items-center gap-1">
                {tagTeamList.map((ttKey) => (
                  <span
                    key={ttKey}
                    className="flex items-center gap-1 px-1.5 py-0.5 rounded bg-hazard-purple/20 border border-hazard-purple/50 text-hazard-purple text-[10px] font-bold"
                  >
                    <span>{ttKey}</span>
                    <button
                      type="button"
                      onClick={() => handleToggleTagTeam(key, tagTeamList, ttKey)}
                      className="hover:text-rose-400"
                    >
                      <X className="w-2.5 h-2.5" />
                    </button>
                  </span>
                ))}

                {/* Quick Tag-Team Selector Dropdown */}
                <select
                  value=""
                  onChange={(e) => {
                    if (e.target.value) {
                      handleToggleTagTeam(key, tagTeamList, e.target.value);
                    }
                  }}
                  className="bg-hazard-card border border-hazard-border text-hazard-textMuted text-[10px] rounded px-1 py-0.5 outline-none hover:text-white"
                >
                  <option value="">+ Inherit...</option>
                  {allLibraryOptions
                    .filter((o) => o.key !== key && !tagTeamList.includes(o.key))
                    .map((opt) => (
                      <option key={opt.key} value={opt.key}>
                        {opt.name} ({opt.key})
                      </option>
                    ))}
                </select>
              </div>

