1	import React, { useState, useRef, useEffect, useMemo } from 'react';
2	import { ConditionEntry } from '../../types/schema';
3	import { ConditionManager } from '../../utils/conditionManager';
4	import { generateHexId } from '../../utils/hexId';
5	import { getCategoryBadgeStyle } from './NotionCategorySelect';
6	import {
7	  Plus,
8	  Check,
9	  X,
10	  Search,
11	  ChevronDown,
12	  Sparkles,
13	  Layers,
14	  Folder,
15	  Tag,
16	} from 'lucide-react';
17	
18	interface NotionConditionMultiSelectProps {
19	  selectedIds: string[]; // Array of Condition Hex IDs (or fallback raw keywords)
20	  conditions: Record<string, ConditionEntry>; // Condition registry
21	  variant: 'requirement' | 'impact'; // requirement: emerald, impact: cyan
22	  onChange: (updatedIds: string[]) => void;
23	  onConditionCreated?: (newId: string, newEntry: ConditionEntry) => void;
24	}
25	
26	export const NotionConditionMultiSelect: React.FC<NotionConditionMultiSelectProps> = ({
27	  selectedIds,
28	  conditions,
29	  variant,
30	  onChange,
31	  onConditionCreated,
32	}) => {
33	  const [isOpen, setIsOpen] = useState(false);
34	  const [search, setSearch] = useState('');
35	  const popoverRef = useRef<HTMLDivElement>(null);
36	  const searchInputRef = useRef<HTMLInputElement>(null);
37	
38	  // Close on outside click
39	  useEffect(() => {
40	    const handleClickOutside = (e: MouseEvent) => {
41	      if (popoverRef.current && !popoverRef.current.contains(e.target as Node)) {
42	        setIsOpen(false);
43	        setSearch('');
44	      }
45	    };
46	    if (isOpen) {
47	      document.addEventListener('mousedown', handleClickOutside);
48	      setTimeout(() => searchInputRef.current?.focus(), 50);
49	    }
50	    return () => document.removeEventListener('mousedown', handleClickOutside);
51	  }, [isOpen]);
52	
53	  // Clean list of conditions as array
54	  const allConditionsList = useMemo(() => {
55	    return Object.entries(conditions).map(([id, entry]) => ({
56	      id,
57	      name: entry.display_name || id,
58	      category: entry.category || 'General',
59	      description: entry.description || '',
60	      completed: Boolean(entry.completed),
61	    }));
62	  }, [conditions]);
63	
64	  // Group conditions by Category
65	  const groupedConditions = useMemo(() => {
66	    const groups: Record<string, typeof allConditionsList> = {};
67	    const q = search.toLowerCase().trim();
68	
69	    allConditionsList.forEach((cond) => {
70	      // Filter by search
