24	
25	interface OptionEditorModalProps {
26	  isOpen: boolean;
27	  onClose: () => void;
28	  fileRelPath: string;
29	  fileDisplayName: string;
30	  initialKey?: string | null;
31	  initialEntry?: ComponentEntry | null;
32	  onSaved?: (savedKey: string) => void;
33	}
34	
35	export const OptionEditorModal: React.FC<OptionEditorModalProps> = ({
36	  isOpen,
37	  onClose,
38	  fileRelPath,
39	  fileDisplayName,
40	  initialKey,
41	  initialEntry,
42	  onSaved,
43	}) => {
44	  const { app, folders, matrixDomains, reload } = useTriggerStore();
45	
46	  const isEditing = Boolean(initialKey);
47	
48	  // Form States
49	  const [key, setKey] = useState('');
50	  const [displayName, setDisplayName] = useState('');
51	  const [prompt, setPrompt] = useState('');
52	  const [image, setImage] = useState('');
53	  const [tagTeam, setTagTeam] = useState<string[]>([]);
54	  const [antiPrompt, setAntiPrompt] = useState('');
55	  const [requirements, setRequirements] = useState<string[]>([]);
56	  const [impacts, setImpacts] = useState<string[]>([]);
57	  const [females, setFemales] = useState(0);
58	  const [males, setMales] = useState(0);
59	  const [isLocked, setIsLocked] = useState(false);
60	  const [lockKey, setLockKey] = useState('');
61	  const [isCompleted, setIsCompleted] = useState(false);
62	  const [description, setDescription] = useState('');
63	
64	  // Auxiliary Input helpers
65	  const [newReqInput, setNewReqInput] = useState('');
66	  const [newImpactInput, setNewImpactInput] = useState('');
67	  const [tagTeamSearch, setTagTeamSearch] = useState('');
68	  const [isSaving, setIsSaving] = useState(false);
69	  const [errorMsg, setErrorMsg] = useState('');
70	
71	  // Initialize or reset form values
72	  useEffect(() => {
73	    if (isOpen) {
74	      if (initialKey && initialEntry) {
75	        setKey(initialKey);
76	        setDisplayName(initialEntry.display_name || initialKey);
77	        setPrompt(initialEntry.prompt || '');
78	        setImage(initialEntry.image || initialEntry.thumbnail || '');
79	        setTagTeam(Array.isArray(initialEntry.tag_team) ? initialEntry.tag_team : []);
80	        setAntiPrompt(
81	          typeof initialEntry['anti-prompt'] === 'string'
82	            ? initialEntry['anti-prompt']
83	            : Array.isArray(initialEntry.exclude)
84	            ? initialEntry.exclude.join(', ')
85	            : ''
86	        );
87	        setRequirements(
88	          Array.isArray(initialEntry.requirement)
89	            ? initialEntry.requirement
90	            : Array.isArray(initialEntry.require)
91	            ? initialEntry.require
92	            : []
93	        );
94	        setImpacts(
95	          Array.isArray(initialEntry.impact)
96	            ? initialEntry.impact
97	            : Array.isArray(initialEntry.keywords)
98	            ? initialEntry.keywords
99	            : []
100	        );
101	        if (Array.isArray(initialEntry.subjects) && initialEntry.subjects.length >= 2) {
102	          setFemales(initialEntry.subjects[0]);
103	          setMales(initialEntry.subjects[1]);
104	        } else {
105	          setFemales(0);
106	          setMales(0);
107	        }
108	        setIsLocked(Boolean(initialEntry.locked || initialEntry.lock));
109	        setLockKey(initialEntry.lockKey || '');
110	        setIsCompleted(Boolean(initialEntry.completed));
111	        setDescription(initialEntry.description || '');
112	      } else {
113	        // Create new option: generate fresh Hex ID
114	        const freshHex = generateHexId();
115	        setKey(freshHex);
116	        setDisplayName('');
117	        setPrompt('');
118	        setImage('');
119	        setTagTeam([]);
120	        setAntiPrompt('');
121	        setRequirements([]);
122	        setImpacts([]);
123	        setFemales(0);
124	        setMales(0);
125	        setIsLocked(false);
126	        setLockKey('');
127	        setIsCompleted(false);
128	        setDescription('');
129	      }
130	      setErrorMsg('');
131	      setIsSaving(false);
132	    }
133	  }, [isOpen, initialKey, initialEntry]);
134	
135	  // Flat lookup of all existing options across the entire vault for Tag-Team inheritance
136	  const allAvailableOptions = useMemo(() => {
137	    const list: { key: string; name: string; fileRelPath: string; prompt: string; fileName: string }[] = [];
138	    folders.forEach((folder) => {
139	      folder.files.forEach((file) => {
140	        Object.entries(file.entries).forEach(([optKey, optEntry]) => {
141	          list.push({
142	            key: optKey,
143	            name: optEntry.display_name || optKey,
144	            fileRelPath: file.relPath,
145	            prompt: optEntry.prompt || '',
146	            fileName: file.displayName,
147	          });
148	        });
149	      });
150	    });
151	    matrixDomains.forEach((domain) => {
152	      domain.files.forEach((file) => {
153	        Object.entries(file.entries).forEach(([optKey, optEntry]) => {
154	          list.push({
155	            key: optKey,
156	            name: optEntry.display_name || optKey,
157	            fileRelPath: file.relPath,
158	            prompt: optEntry.prompt || '',
159	            fileName: file.displayName,
160	          });
161	        });
162	      });
163	    });
164	    return list;
165	  }, [folders, matrixDomains]);
166	
167	  // Filtered list for Tag-Team search
168	  const filteredTagTeamOptions = useMemo(() => {
169	    if (!tagTeamSearch.trim()) return allAvailableOptions.slice(0, 15);
170	    const q = tagTeamSearch.toLowerCase();
171	    return allAvailableOptions
172	      .filter(
173	        (o) =>
174	          o.key.toLowerCase().includes(q) ||
175	          o.name.toLowerCase().includes(q) ||
176	          o.fileName.toLowerCase().includes(q)
177	      )
178	      .slice(0, 15);
179	  }, [allAvailableOptions, tagTeamSearch]);
180	
181	  // Live compiled prompt sandbox preview: Own Prompt + TagTeam Prompts - AntiPrompt
182	  const calculatedPromptPreview = useMemo(() => {
183	    const tokens: string[] = [];
184	
185	    // 1. Own prompt tokens
186	    if (prompt.trim()) {
187	      prompt
188	        .split(',')
189	        .map((t) => t.trim())
190	        .filter(Boolean)
191	        .forEach((t) => tokens.push(t));
192	    }
193	
194	    // 2. Tag-team inherited prompt tokens
195	    tagTeam.forEach((ttKey) => {
196	      const target = allAvailableOptions.find((o) => o.key === ttKey);
197	      if (target && target.prompt) {
198	        target.prompt
199	          .split(',')
200	          .map((t) => t.trim())
201	          .filter(Boolean)
202	          .forEach((t) => tokens.push(t));
203	      }
204	    });
205	
206	    // 3. Subtractions via Anti-Prompt
207	    const antiTokens = antiPrompt
208	      .split(',')
209	      .map((t) => t.trim().toLowerCase())
210	      .filter(Boolean);
211	
212	    const finalTokens = tokens.filter((t) => !antiTokens.includes(t.toLowerCase()));
213	    return Array.from(new Set(finalTokens)).join(', ');
214	  }, [prompt, tagTeam, antiPrompt, allAvailableOptions]);
215	
216	  // Handlers for Requirements & Impacts tag lists
217	  const handleAddRequirement = () => {
218	    const val = newReqInput.trim().toLowerCase();
219	    if (val && !requirements.includes(val)) {
220	      setRequirements([...requirements, val]);
221	      setNewReqInput('');
222	    }
223	  };
224	
225	  const handleRemoveRequirement = (req: string) => {
226	    setRequirements(requirements.filter((r) => r !== req));
227	  };
228	
229	  const handleAddImpact = () => {
230	    const val = newImpactInput.trim().toLowerCase();
231	    if (val && !impacts.includes(val)) {
232	      setImpacts([...impacts, val]);
233	      setNewImpactInput('');
234	    }
235	  };
236	
237	  const handleRemoveImpact = (imp: string) => {
238	    setImpacts(impacts.filter((i) => i !== imp));
239	  };
240	
241	  const handleToggleTagTeam = (optKey: string) => {
242	    if (tagTeam.includes(optKey)) {
243	      setTagTeam(tagTeam.filter((k) => k !== optKey));
244	    } else {
245	      setTagTeam([...tagTeam, optKey]);
246	    }
247	  };
248	
249	  // Submit & Save directly to file
250	  const handleSave = async (e: React.FormEvent) => {
251	    e.preventDefault();
252	    if (!app) return;
253	
254	    const cleanKey = key.trim();
255	    if (!cleanKey) {
256	      setErrorMsg('Option Key / Hex ID is required.');
257	      return;
258	    }
259	    if (!displayName.trim()) {
260	      setErrorMsg('Display Name is required.');
261	      return;
262	    }
263	
264	    setIsSaving(true);
265	    setErrorMsg('');
266	
267	    const entryToSave: ComponentEntry = {
268	      display_name: displayName.trim(),
269	      prompt: prompt.trim(),
270	      image: image.trim() || undefined,
271	      description: description.trim() || undefined,
272	      tag_team: tagTeam.length > 0 ? tagTeam : undefined,
273	      'anti-prompt': antiPrompt.trim() || undefined,
274	      requirement: requirements.length > 0 ? requirements : undefined,
275	      impact: impacts.length > 0 ? impacts : undefined,
276	      // Backward compatibility aliases
277	      keywords: impacts.length > 0 ? impacts : undefined,
278	      require: requirements.length > 0 ? requirements : undefined,
279	      exclude: antiPrompt
280	        .split(',')
281	        .map((t) => t.trim())
282	        .filter(Boolean),
283	      subjects: females !== 0 || males !== 0 ? [females, males] : undefined,
284	      locked: isLocked ? true : undefined,
285	      lockKey: isLocked && lockKey.trim() ? lockKey.trim() : undefined,
286	      completed: isCompleted ? true : undefined,
287	    };
288	
289	    const success = await ComponentManager.saveEntry(
290	      app,
291	      fileRelPath,
292	      cleanKey,
293	      entryToSave,
294	      initialKey || undefined
295	    );
296	
297	    if (success) {
298	      await reload();
299	      if (onSaved) onSaved(cleanKey);
300	      onClose();
301	    } else {
302	      setErrorMsg(`Failed to write entry to file at ${fileRelPath}. Check console logs.`);
303	      setIsSaving(false);
304	    }
305	  };
306	
307	  if (!isOpen) return null;
308	
309	  return (
310	    <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-black/85 backdrop-blur-xl animate-fadeIn">
311	      <div className="flex flex-col w-full max-w-4xl max-h-[90vh] bg-hazard-card border-2 border-hazard-gold/60 rounded-3xl shadow-2xl overflow-hidden">
312	        {/* Modal Header */}
313	        <div className="flex items-center justify-between p-5 border-b border-hazard-border bg-hazard-void shrink-0">
314	          <div className="flex items-center gap-3">
315	            <div className="flex items-center justify-center w-10 h-10 rounded-xl bg-hazard-gold/10 border border-hazard-gold/30 text-hazard-gold shadow-hazard-glow">
316	              <Sparkles className="w-5 h-5" />
317	            </div>
318	            <div>
319	              <div className="flex items-center gap-2">
320	                <h3 className="text-base font-bold uppercase tracking-wider text-hazard-textBright">
321	                  {isEditing ? 'Edit Component Option' : 'Create New Component Option'}
322	                </h3>
323	                <span className="px-2 py-0.5 rounded-md bg-hazard-gold/15 border border-hazard-gold/40 text-hazard-gold text-[10px] font-mono font-bold">
324	                  {fileDisplayName}
325	                </span>
326	              </div>
327	              <p className="text-xs text-hazard-textMuted font-mono mt-0.5">
328	                Target: <code className="text-hazard-cyan">{fileRelPath}</code>
329	              </p>
330	            </div>
331	          </div>
332	
333	          <button
334	            type="button"
335	            onClick={onClose}
336	            className="p-2 text-hazard-textMuted hover:text-white bg-hazard-card border border-hazard-border rounded-xl transition hover:border-hazard-gold/50"
337	          >
338	            <X className="w-5 h-5" />
339	          </button>
340	        </div>
341	
342	        {/* Modal Body / Scrollable Form */}
343	        <form onSubmit={handleSave} className="flex-1 p-6 overflow-y-auto flex flex-col gap-6">
344	          {errorMsg && (
345	            <div className="p-3 rounded-xl bg-rose-950/80 border border-rose-500 text-rose-300 text-xs font-mono flex items-center gap-2">
346	              <AlertTriangle className="w-4 h-4 shrink-0" />
347	              <span>{errorMsg}</span>
348	            </div>
349	          )}
350	
351	          {/* Section 1: Identifiers (Hex ID & Display Name) */}
352	          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
353	            {/* Hex ID / Key */}
354	            <div className="flex flex-col gap-1.5">
355	              <div className="flex items-center justify-between">
356	                <label className="text-xs font-bold uppercase tracking-wider text-hazard-textBright font-mono">
357	                  Unique Key (Hex ID) *
358	                </label>
359	                <button
360	                  type="button"
361	                  onClick={() => setKey(generateHexId())}
362	                  title="Generate Fresh Timestamp Hex ID"
363	                  className="flex items-center gap-1 text-[10px] font-mono text-hazard-gold hover:underline"
364	                >
365	                  <RefreshCw className="w-3 h-3" />
366	                  <span>Gen Hex</span>
367	                </button>
368	              </div>
369	              <input
370	                type="text"
371	                value={key}
372	                onChange={(e) => setKey(e.target.value)}
373	                placeholder="e.g. 1951ab89f3c"
374	                required
375	                className="w-full px-3.5 py-2.5 rounded-xl bg-hazard-void border border-hazard-border focus:border-hazard-gold text-xs font-mono text-hazard-gold outline-none"
376	              />
377	              <span className="text-[10px] text-hazard-textMuted font-mono">
378	                Decoded: {formatHexDate(key)}
379	              </span>
380	            </div>
381	
382	            {/* Human Display Name */}
383	            <div className="flex flex-col gap-1.5">
384	              <label className="text-xs font-bold uppercase tracking-wider text-hazard-textBright font-mono">
385	                Display Name *
386	              </label>
387	              <input
388	                type="text"
389	                value={displayName}
390	                onChange={(e) => setDisplayName(e.target.value)}
391	                placeholder="e.g. Cyberpunk Bodysuit (Wet)"
392	                required
393	                className="w-full px-3.5 py-2.5 rounded-xl bg-hazard-void border border-hazard-border focus:border-hazard-gold text-xs text-hazard-textBright outline-none font-bold"
394	              />
395	              <span className="text-[10px] text-hazard-textMuted font-mono">
396	                Title displayed on component selector cards.
397	              </span>
398	            </div>
399	          </div>
400	
401	          {/* Section 2: Image Preview & Description */}
402	          <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
403	            <div className="sm:col-span-2 flex flex-col gap-1.5">
404	              <label className="text-xs font-bold uppercase tracking-wider text-hazard-textBright font-mono">
405	                Image / Thumbnail URL
406	              </label>
407	              <input
408	                type="text"
409	                value={image}
410	                onChange={(e) => setImage(e.target.value)}
411	                placeholder="https://... or local path"
412	                className="w-full px-3.5 py-2.5 rounded-xl bg-hazard-void border border-hazard-border focus:border-hazard-gold text-xs font-mono text-hazard-textBright outline-none"
413	              />
414	              <span className="text-[10px] text-hazard-textMuted font-mono">
415	                Optional 1:1 preview tile image for this option.
416	              </span>
417	            </div>
418	
419	            {/* Thumbnail Preview Box */}
420	            <div className="flex items-center gap-3 p-3 rounded-xl bg-hazard-void border border-hazard-border">
421	              <div className="w-14 h-14 rounded-lg bg-hazard-card border border-hazard-border/80 overflow-hidden flex items-center justify-center shrink-0">
422	                {image ? (
423	                  <img src={image} alt="Preview" className="w-full h-full object-cover" />
424	                ) : (
425	                  <Sparkles className="w-6 h-6 text-hazard-gold/50" />
426	                )}
427	              </div>
428	              <span className="text-[10px] text-hazard-textMuted font-mono">
429	                {image ? 'Valid Image URL' : 'Fallback Icon Active'}
430	              </span>
431	            </div>
432	          </div>
433	
434	          {/* Section 3: Prompt Textarea */}
435	          <div className="flex flex-col gap-1.5">
436	            <label className="text-xs font-bold uppercase tracking-wider text-hazard-textBright font-mono">
437	              Base Prompt Tokens *
438	            </label>
439	            <textarea
440	              rows={3}
441	              value={prompt}
442	              onChange={(e) => setPrompt(e.target.value)}
443	              placeholder="e.g. wet clothes, translucent shirt, soaked fabric"
444	              className="w-full p-3.5 rounded-xl bg-hazard-void border border-hazard-border focus:border-hazard-gold text-xs font-mono text-hazard-textBright outline-none leading-relaxed resize-none"
445	            />
446	            <span className="text-[10px] text-hazard-textMuted font-mono">
447	              Comma-separated tokens directly supplied by this option. Supports <code>{'{opt1|opt2}'}</code> permutation syntax.
448	            </span>
449	          </div>
450	
451	          {/* Section 4: Tag-Team (Prompt Inheritance) & Anti-Prompt */}
452	          <div className="flex flex-col gap-3 p-4 rounded-2xl bg-hazard-void/90 border border-hazard-border">
453	            <div className="flex items-center justify-between">
454	              <div className="flex items-center gap-2">
455	                <Layers className="w-4 h-4 text-hazard-purple" />
456	                <span className="text-xs font-bold uppercase tracking-wider text-hazard-purple font-mono">
457	                  Tag-Team Prompt Inheritance
458	                </span>
459	              </div>
460	              <span className="text-[10px] font-mono text-hazard-textMuted">
461	                {tagTeam.length} inherited components
462	              </span>
463	            </div>
464	
465	            {/* Tag-Team Selector & Search */}
466	            <div className="flex flex-col gap-2">
467	              <div className="flex items-center gap-2 bg-hazard-card border border-hazard-border rounded-xl px-3 py-1.5">
468	                <Search className="w-3.5 h-3.5 text-hazard-textMuted" />
469	                <input
470	                  type="text"
471	                  placeholder="Search other components to inherit prompt tokens from..."
472	                  value={tagTeamSearch}
473	                  onChange={(e) => setTagTeamSearch(e.target.value)}
474	                  className="w-full bg-transparent text-xs text-hazard-textBright placeholder:text-hazard-textMuted/50 outline-none"
475	                />
476	              </div>
477	
478	              {/* Tag-Team Active Badges */}
479	              {tagTeam.length > 0 && (
480	                <div className="flex flex-wrap gap-1.5 p-2 rounded-xl bg-hazard-card border border-hazard-purple/40">
481	                  {tagTeam.map((ttKey) => {
482	                    const match = allAvailableOptions.find((o) => o.key === ttKey);
483	                    return (
484	                      <span
485	                        key={ttKey}
486	                        className="flex items-center gap-1.5 px-2 py-0.5 rounded-lg bg-hazard-purple/20 border border-hazard-purple/60 text-hazard-purple text-[11px] font-mono font-bold"
487	                      >
488	                        <span>{match?.name || ttKey}</span>
489	                        <button
490	                          type="button"
491	                          onClick={() => handleToggleTagTeam(ttKey)}
492	                          className="hover:text-hazard-crimson"
493	                        >
494	                          <X className="w-3 h-3" />
495	                        </button>
496	                      </span>
497	                    );
498	                  })}
499	                </div>
500	              )}
501	
502	              {/* Tag-Team Search Results Picker */}
503	              <div className="flex flex-wrap gap-1.5 max-h-24 overflow-y-auto p-1">
504	                {filteredTagTeamOptions.map((opt) => {
505	                  const isSelected = tagTeam.includes(opt.key);
506	                  return (
507	                    <button
508	                      key={opt.key}
509	                      type="button"
510	                      onClick={() => handleToggleTagTeam(opt.key)}
511	                      className={`flex items-center gap-1 px-2 py-1 rounded-lg text-[10px] font-mono transition ${
512	                        isSelected
513	                          ? 'bg-hazard-purple text-white font-bold'
514	                          : 'bg-hazard-card border border-hazard-border text-hazard-textMuted hover:text-white'
515	                      }`}
516	                    >
517	                      <span>{opt.name}</span>
518	                      <span className="text-[9px] opacity-60">({opt.fileName})</span>
519	                    </button>
