      {requirements.map((req) => (
        <span
          key={req}
          className="flex items-center gap-1 px-2 py-0.5 rounded-md bg-emerald-950/60 border border-emerald-500/40 text-emerald-300 text-[10px] font-mono"
        >
          <span>{req}</span>
          <button
            type="button"
            onClick={() => handleRemoveRequirement(req)}
            className="hover:text-rose-400"
          >
            <X className="w-3 h-3" />
          </button>
        </span>
      ))}
    </div>
  </div>

  {/* Impacts (Conditions Asserted) */}
  <div className="flex flex-col gap-2 p-4 rounded-2xl bg-hazard-void border border-hazard-border">
    <label className="text-xs font-bold uppercase tracking-wider text-hazard-cyan font-mono">
      Impacts (Conditions Asserted)
    </label>
    <div className="flex items-center gap-2">
      <input
        type="text"
        value={newImpactInput}
        onChange={(e) => setNewImpactInput(e.target.value)}
        onKeyDown={(e) => {
          if (e.key === 'Enter') {
            e.preventDefault();
            handleAddImpact();
          }
        }}
        placeholder="e.g. cond_wet_state, wet_clothes"
        className="w-full px-3 py-1.5 rounded-xl bg-hazard-card border border-hazard-border text-xs font-mono text-hazard-cyan outline-none"
      />
      <button
        type="button"
        onClick={handleAddImpact}
        className="p-2 rounded-xl bg-cyan-950/80 border border-cyan-500/50 text-hazard-cyan hover:bg-hazard-cyan hover:text-black transition"
      >
        <Plus className="w-3.5 h-3.5" />
      </button>
    </div>
    <div className="flex flex-wrap gap-1.5 min-h-[36px]">
      {impacts.map((imp) => (
        <span
          key={imp}
          className="flex items-center gap-1 px-2 py-0.5 rounded-md bg-cyan-950/60 border border-cyan-500/40 text-cyan-300 text-[10px] font-mono"
        >
          <span>{imp}</span>
          <button
            type="button"
            onClick={() => handleRemoveImpact(imp)}
            className="hover:text-rose-400"
          >
            <X className="w-3 h-3" />
          </button>
        </span>
      ))}
    </div>
  </div>
</div>

