8	  Preset,
9	} from '../types/schema';
10	import {
11	  DEFAULT_CATEGORIES,
12	  DEFAULT_NODES,
13	  DEFAULT_GACHA_POOLS,
14	  DEFAULT_WILDCARDS,
15	  DEFAULT_EXCLUSIONS,
16	  DEFAULT_PRESETS,
17	} from '../engine/defaultData';
18	
19	export const DATA_FOLDER_PATH = 'Hazard_Trigger_Data';
20	
21	export interface HazardVaultData {
22	  categories: Category[];
23	  nodes: PromptNode[];
24	  gachaPools: GachaPool[];
25	  wildcards: WildcardRegistry;
26	  exclusions: ExclusionConfig;
27	  presets: Preset[];
28	}
29	
30	export class VaultIoManager {
31	  private static getPath(filename: string): string {
32	    return normalizePath(`${DATA_FOLDER_PATH}/${filename}`);
33	  }
34	
35	  /**
36	   * Initializes the vault data folder and creates default JSON files if missing.
37	   */
38	  public static async bootstrap(app: App): Promise<HazardVaultData> {
39	    const adapter = app.vault.adapter;
40	    const folderExists = await adapter.exists(DATA_FOLDER_PATH);
41	
42	    if (!folderExists) {
43	      try {
44	        await adapter.mkdir(DATA_FOLDER_PATH);
45	      } catch (e) {
46	        console.warn('[Hazard Trigger] Folder creation note:', e);
47	      }
48	    }
49	
50	    const filesToSeed: { name: string; data: any }[] = [
51	      { name: 'categories.json', data: DEFAULT_CATEGORIES },
52	      { name: 'prompt_nodes.json', data: DEFAULT_NODES },
53	      { name: 'gacha_pools.json', data: DEFAULT_GACHA_POOLS },
54	      { name: 'wildcards.json', data: DEFAULT_WILDCARDS },
55	      { name: 'exclusions.json', data: DEFAULT_EXCLUSIONS },
56	      { name: 'presets.json', data: DEFAULT_PRESETS },
57	    ];
58	
59	    for (const file of filesToSeed) {
60	      const filePath = this.getPath(file.name);
61	      const exists = await adapter.exists(filePath);
62	      if (!exists) {
63	        await adapter.write(filePath, JSON.stringify(file.data, null, 2));
