const handleSaveToDisk = useCallback(async () => {
  if (!app || isSaving) return;
  setIsSaving(true);

  const success = await ConditionManager.saveAllConditions(app, workingConditions);
  if (success) {
    setConditions(JSON.parse(JSON.stringify(workingConditions)));
    setIsDirty(false);
    setDirtyCount(0);
    setSaveSuccessNotice(true);
    setTimeout(() => setSaveSuccessNotice(false), 2000);
    await reload();
