import React, { useState } from 'react';
import { useTriggerStore } from '../../store/useTriggerStore';
import { HazardTemplate } from '../../types/schema';
import {
  Bookmark,
  BookmarkPlus,
  Play,
  Trash2,
  Save,
  Search,
  Tag,
  Layers,
  Calendar,
  RefreshCw,
  FileCode,
  Dices,
  Check,
  Unlock,
  Key,
} from 'lucide-react';

interface TemplatesViewProps {
  onOpenSaveModal: () => void;
  onApplyAndNavigate: (template: HazardTemplate) => void;
}

export const TemplatesView: React.FC<TemplatesViewProps> = ({
  onOpenSaveModal,
  onApplyAndNavigate,
}) => {
  const {
    templates,
    activeTemplate,
    loadTemplates,
    deleteTemplate,
    updateActiveTemplate,
    isTemplatesLoading,
    isSaving,
    folders,
  } = useTriggerStore();

  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string>('all');
  const [deletingId, setDeletingId] = useState<string | null>(null);

  // Extract all categories
  const categories = Array.from(
    new Set(templates.map((t) => t.category || 'General').filter(Boolean))
  );

  // Filter templates
  const filteredTemplates = templates.filter((tpl) => {
    const matchesSearch =
      tpl.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      (tpl.description && tpl.description.toLowerCase().includes(searchQuery.toLowerCase())) ||
      (tpl.tags && tpl.tags.some((t) => t.toLowerCase().includes(searchQuery.toLowerCase())));

    const matchesCategory =
      selectedCategory === 'all' || (tpl.category || 'General') === selectedCategory;

        telemetry.isPOV
          ? 'bg-hazard-crimson/10 border-hazard-crimson/50 text-hazard-crimson font-bold'
          : 'bg-hazard-void border-hazard-border text-hazard-textMuted'
      }`}
    >
      <Eye className="w-3.5 h-3.5" />
      <span>POV: {telemetry.isPOV ? 'ENGAGED' : '3RD PERSON'}</span>
    </div>
  </div>
</div>

