47	export class ConditionManager {
48	  /** Sanitizes a ConditionEntry to strictly conform to the clean V2 schema. */
49	  public static sanitizeCondition(raw: any): ConditionEntry {
50	    const clean: ConditionEntry = {
51	      display_name: raw.display_name || 'Unnamed Condition',
52	      category: raw.category || 'General',
53	      description: raw.description || '',
54	    };
55	
56	    if (raw.completed === true) clean.completed = true;
57	    if (Array.isArray(raw.tag_team) && raw.tag_team.length > 0) clean.tag_team = raw.tag_team.filter(Boolean);
58	    if (Array.isArray(raw.conflicts_with) && raw.conflicts_with.length > 0) clean.conflicts_with = raw.conflicts_with.filter(Boolean);
59	    return clean;
60	  }
