62	  /** Creates the mirrored Conditions folder structure and migrates the legacy root table once. */
63	  public static async ensureConditionsFolder(app: App): Promise<void> {
64	    const adapter = app.vault.adapter;
65	    const root = cleanPath(CONDITIONS_DIR);
66	    const core = cleanPath(`${CONDITIONS_DIR}/_00_Core`);
67	    const legacy = cleanPath(`${CONDITIONS_DIR}/conditions.json`);
68	    const migrated = cleanPath(CONDITIONS_FILE_PATH);
69	
70	    if (!(await adapter.exists(root))) await adapter.mkdir(root);
71	    if (!(await adapter.exists(core))) await adapter.mkdir(core);
72	
73	    if (await adapter.exists(legacy) && !(await adapter.exists(migrated))) {
74	      await adapter.rename(legacy, migrated);
