  const list = Array.isArray(currentTagTeam) ? [...currentTagTeam] : [];
  const exists = list.includes(targetKey);
  const updated = exists ? list.filter((k) => k !== targetKey) : [...list, targetKey];
  updateEntryField(key, 'tag_team', updated);
};

