1	import { ComponentFolderNode, ComponentFileNode, ComponentEntry } from './componentScanner';
2	import { MatrixDomainNode, MatrixStateDefinition } from '../types/schema';
3	
4	export interface MatchedSectionResult {
5	  folderDisplayName: string;
6	  folderRelPath: string;
7	  fileDisplayName: string;
8	  fileRelPath: string;
9	  isMatrixDomain?: boolean;
10	  domainId?: string;
11	  matchedEntryKey: string;
12	  matchedEntry: ComponentEntry;
13	  matchedTokens: string[];
14	  confidence: number; // 0 to 100
15	  matchType: 'exact' | 'strong' | 'partial' | 'keyword';
16	}
17	
18	export interface MatchedMatrixStateResult {
19	  domainId: string;
20	  domainDisplayName: string;
21	  state: MatrixStateDefinition;
22	  matchedTokens: string[];
23	  confidence: number;
24	}
25	
26	export interface TokenAnalysis {
27	  original: string;
28	  clean: string;
29	  isMatched: boolean;
30	  matchedSection?: string;
31	  matchedFile?: string;
32	  matchedEntryKey?: string;
33	  matchedEntryName?: string;
34	  color?: string;
35	  isMatrixState?: boolean;
36	  weight?: number;
37	}
38	
39	export interface DecompiledPromptResult {
40	  rawPrompt: string;
41	  tokensCount: number;
42	  matchedSections: MatchedSectionResult[];
43	  matchedMatrixStates: MatchedMatrixStateResult[];
44	  tokenAnalyses: TokenAnalysis[];
45	  unmatchedTokens: string[];
46	  matchedTokensCount: number;
47	  matchPercentage: number;
48	  detectedTelemetry: {
49	    females: number;
50	    males: number;
51	    isSolo: boolean;
52	    isPOV: boolean;
53	  };
54	  recommendedSelections: Record<string, string>;
55	  recommendedMatrixBase: Record<string, string[]>;
56	  recommendedMatrixUnlocked: Record<string, string[]>;
57	}
58	
59	/**
60	 * Strips weights, parentheses, and extra syntax from a token.
61	 * E.g., `(masterpiece:1.2)` -> `{ clean: "masterpiece", weight: 1.2 }`
62	 */
63	export function sanitizeToken(raw: string): { clean: string; weight: number } {
64	  let text = raw.trim();
65	  let weight = 1.0;
66	
67	  // Check for (token:weight) or (token:1.2)
68	  const weightMatch = text.match(/^\(?([a-zA-Z0-9_\-\s]+):([0-9.]+)\)?$/);
69	  if (weightMatch) {
70	    text = weightMatch[1].trim();
71	    weight = parseFloat(weightMatch[2]) || 1.0;
72	  } else {
73	    // Strip leading/trailing (, ), [, ], {, }
74	    text = text.replace(/^[([{<]+|[)\]}>]+$/g, '').trim();
75	  }
76	
77	  return {
78	    clean: text.toLowerCase().replace(/_/g, ' '),
79	    weight,
80	  };
81	}
82	
83	/**
84	 * Splits raw prompt into token segments separated by comma, newlines, or BREAK.
85	 */
86	export function extractRawTokens(promptText: string): string[] {
87	  if (!promptText || !promptText.trim()) return [];
88	
89	  return promptText
90	    .split(/[\n,]+/)
91	    .map((t) => t.trim())
92	    .filter((t) => t && t.toUpperCase() !== 'BREAK');
93	}
94	
95	/**
96	 * Decompiles and reverse-engineers a complete prompt string against the active
97	 * components and matrix domains database.
98	 */
99	export function decompilePrompt(
100	  promptText: string,
101	  folders: ComponentFolderNode[] = [],
102	  matrixDomains: MatrixDomainNode[] = []
103	): DecompiledPromptResult {
104	  const safeFolders = folders || [];
105	  const safeDomains = matrixDomains || [];
106	  const rawTokens = extractRawTokens(promptText);
107	  const promptLower = (promptText || '').toLowerCase();
108	
109	  // 1. Gather all file nodes from Component Folders and Matrix Domains
110	  interface FileContainer {
111	    folderDisplayName: string;
112	    folderRelPath: string;
113	    file: ComponentFileNode;
114	    isMatrixDomain: boolean;
115	    domainId?: string;
116	  }
117	
118	  const allContainers: FileContainer[] = [
119	    ...safeFolders.flatMap((f) =>
120	      (f.files || []).map((file) => ({
121	        folderDisplayName: f.displayName,
122	        folderRelPath: f.relPath,
123	        file,
124	        isMatrixDomain: false,
125	      }))
126	    ),
127	    ...safeDomains.flatMap((d) =>
128	      (d.files || []).map((file) => ({
129	        folderDisplayName: d.displayName,
130	        folderRelPath: d.relPath,
131	        file,
132	        isMatrixDomain: true,
133	        domainId: d.domainId,
134	      }))
135	    ),
136	  ];
137	
138	  const matchedSections: MatchedSectionResult[] = [];
139	  const matchedMatrixStates: MatchedMatrixStateResult[] = [];
140	  const matchedTokenIndices = new Set<number>();
141	  const tokenAnalyses: TokenAnalysis[] = [];
142	  const recommendedSelections: Record<string, string> = {};
143	  const recommendedMatrixBase: Record<string, string[]> = {};
144	  const recommendedMatrixUnlocked: Record<string, string[]> = {};
145	
146	  // Pre-process parsed input tokens
147	  const parsedTokens = rawTokens.map((raw) => {
148	    const { clean, weight } = sanitizeToken(raw);
149	    return { raw, clean, weight };
150	  });
151	
152	  // 2. First Pass: Matrix Domain States matching (e.g. emotion / posture base states)
153	  for (const domain of matrixDomains) {
154	    for (const state of domain.states) {
155	      const stateIdClean = state.id.toLowerCase().replace(/_/g, ' ');
156	      const stateLabelClean = state.label.toLowerCase();
157	      const stateBaseTokens = state.basePrompt
158	        ? state.basePrompt
159	            .split(',')
160	            .map((t) => sanitizeToken(t).clean)
161	            .filter(Boolean)
162	        : [];
163	
164	      const matchingTokensForState: string[] = [];
165	
166	      parsedTokens.forEach((tok, idx) => {
167	        if (!tok.clean) return;
168	        const matchesId = tok.clean === stateIdClean || tok.clean.includes(stateIdClean);
169	        const matchesLabel = stateLabelClean.includes(tok.clean);
170	        const matchesBasePrompt = stateBaseTokens.includes(tok.clean);
171	
172	        if (matchesId || matchesLabel || matchesBasePrompt) {
173	          matchingTokensForState.push(tok.raw);
174	          matchedTokenIndices.add(idx);
175	        }
176	      });
177	
178	      if (matchingTokensForState.length > 0) {
179	        matchedMatrixStates.push({
180	          domainId: domain.domainId,
181	          domainDisplayName: domain.displayName,
182	          state,
183	          matchedTokens: Array.from(new Set(matchingTokensForState)),
184	          confidence: Math.min(100, matchingTokensForState.length * 50),
185	        });
186	
187	        if (!recommendedMatrixBase[domain.domainId]) {
188	          recommendedMatrixBase[domain.domainId] = [];
189	        }
190	        if (!recommendedMatrixBase[domain.domainId].includes(state.id)) {
191	          recommendedMatrixBase[domain.domainId].push(state.id);
192	        }
193	      }
194	    }
195	  }
196	
197	  // 3. Second Pass: Component Option Matching across all files
198	  for (const container of allContainers) {
199	    const { file, folderDisplayName, folderRelPath, isMatrixDomain, domainId } = container;
200	    const optionKeys = Object.keys(file.entries);
201	
202	    let bestOptionKey: string | null = null;
203	    let bestOptionEntry: ComponentEntry | null = null;
204	    let bestScore = 0;
205	    let bestMatchedTokens: string[] = [];
206	    let bestMatchType: 'exact' | 'strong' | 'partial' | 'keyword' = 'partial';
207	
208	    for (const key of optionKeys) {
209	      const entry = file.entries[key];
210	      const entryTokens = entry.prompt
211	        ? entry.prompt
212	            .split(',')
213	            .map((t) => sanitizeToken(t).clean)
214	            .filter(Boolean)
215	        : [];
216	      const entryKeywords = (entry.keywords || []).map((k) => sanitizeToken(k).clean);
217	      const entryTags = [
218	        ...(entry.tags || []),
219	        ...(entry.emotions || []),
220	        ...(entry.postures || []),
221	      ].map((t) => sanitizeToken(t).clean);
222	
223	      const entryNameClean = (entry.display_name || key).toLowerCase().replace(/_/g, ' ');
224	      const entryKeyClean = key.toLowerCase().replace(/_/g, ' ');
225	
226	      const matchedTokens: string[] = [];
227	      const matchedIdxs: number[] = [];
228	      let score = 0;
