  matchedComponents: Array<{
    relPath: string;
    folderDisplayName: string;
    fileDisplayName: string;
    entryKey: string;
    entry: ComponentEntry;
    matchedTokenCount: number;
    matchedTokens: string[];
    confidence: number;
  }>;
  reconstructedPrompt: string; // unmatched tokens rejoined
