    const filePath = cleanPath(WORKSPACE_STATE_FILE_PATH);

    try {
      await adapter.write(filePath, JSON.stringify({ ...state, updatedAt: Date.now() }, null, 2));
    } catch (err) {
      console.error('[TemplateManager] Failed to save workspace state:', err);
    }
  }

